function ProductCard({product,onSelect}){const cheapest=product.options.reduce((min,o)=>Math.min(min,o.price_cents),Infinity);return <article className="card group overflow-hidden flex flex-col hover:-translate-y-1 transition-transform duration-300"><button type="button" onClick={()=>onSelect(product)} className="relative h-44 sm:h-56 bg-[#eddfd7] overflow-hidden text-left" aria-label={`Ver detalhes de ${product.name}`}><img src={product.image_url||'/favicon.svg'} alt={`Foto do produto: ${product.name}`} loading="lazy" className="h-full w-full object-cover group-hover:scale-105 transition-transform duration-500" onError={e=>{e.currentTarget.src='/favicon.svg'}}/><span className="absolute top-3 left-3 bg-white/95 px-3 py-1.5 rounded-full text-[10px] font-bold text-cocoa">{product.tag||'Artesanal'}</span></button><div className="p-4 sm:p-5 flex flex-col flex-1"><p className="eyebrow !text-[9px]">{product.category}</p><h3 className="font-display text-xl sm:text-[22px] leading-tight mt-2 min-h-[53px]">{product.name}</h3><p className="text-taupe text-xs leading-[1.7] mt-2 flex-1">{product.description}</p><div className="flex items-end justify-between gap-2 mt-5"><div><p className="text-[10px] text-taupe">Valor</p><strong className="font-display text-[23px] sm:text-[26px]">{money(cheapest)}</strong><p className="text-[10px] text-taupe mt-1">por {product.options?.[0]?.label?.toLowerCase?.()||'unidade'}</p></div><button onClick={()=>onSelect(product)} className="bg-cocoa hover:bg-rose transition text-white text-[11px] font-bold rounded-full px-3 py-3 whitespace-nowrap" aria-label={`Ver ${product.name}`}>Ver doce</button></div></div></article>}
function ProductModal({product,settings,onClose,onAdd}){const [optId,setOptId]=useState(product?.options?.[0]?.id||'');const [qty,setQty]=useState(1);const [wrap,setWrap]=useState(false);const [message,setMessage]=useState('');if(!product)return null;const selected=product.options.find(o=>o.id===optId)||product.options[0];const extra=wrap?(settings?.gift_wrap_cents||0):0;return <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-[2px] grid place-items-center p-3" onClick={onClose}><section className="w-full max-w-[560px] card overflow-hidden max-h-[93vh] overflow-y-auto enter" role="dialog" aria-modal="true" aria-label={'Informações de '+product.name} onClick={e=>e.stopPropagation()}><div className="relative h-52 sm:h-64 bg-blush"><img src={product.image_url} alt={product.name} className="w-full h-full object-cover"/><div className="absolute inset-x-0 bottom-0 p-4 bg-gradient-to-t from-[#2f1f1a]/65 to-transparent"><div className="flex items-center justify-between gap-3"><div><span className="inline-flex bg-white/90 text-cocoa rounded-full px-3 py-1 text-[10px] font-bold uppercase tracking-[.12em]">{product.category}</span><h3 className="font-display text-white text-3xl sm:text-4xl mt-3">{product.name}</h3></div><div className="bg-white/95 rounded-2xl px-4 py-3 text-right shadow"><div className="text-[10px] uppercase tracking-[.12em] text-taupe font-bold">Valor</div><div className="font-display text-2xl text-cocoa">{money(selected.price_cents)}</div><div className="text-[11px] text-taupe">{selected.label}</div></div></div></div><button onClick={onClose} className="absolute top-3 right-3 bg-white rounded-full p-2 shadow min-w-10 min-h-10"><X size={18}/></button></div><div className="p-5 sm:p-6 space-y-4"><p className="eyebrow">Detalhes do doce</p><p className="text-sm text-taupe leading-7">{product.description}</p><div><label className="label">Apresentação</label><div className="flex flex-wrap gap-2">{product.options.map(o=><button key={o.id} className={`chip ${selected.id===o.id?'!bg-cocoa !text-white':''}`} onClick={()=>setOptId(o.id)}>{o.label} · {money(o.price_cents)}</button>)}</div></div><div className="rounded-2xl bg-[#fff7f4] border border-[#f1ddd7] p-4 space-y-3"><div className="flex items-start gap-3"><Gift size={18} className="text-rose mt-0.5"/><div><p className="font-semibold text-sm">Personalize sua encomenda</p><p className="text-[11px] text-taupe mt-1">Escolha embalagem presente e adicione um recado especial para tornar o momento ainda mais carinhoso.</p></div></div><label className="flex gap-3 items-center text-sm cursor-pointer"><input type="checkbox" checked={wrap} onChange={e=>setWrap(e.target.checked)} className="accent-[#b7757f]"/> Embalagem para presente {settings?.gift_wrap_cents>0?`(+ ${money(settings.gift_wrap_cents)} por item)`:''}</label><label className="label">Mensagem especial para cartão (opcional)</label><input className="field" maxLength={120} placeholder="Ex.: Feliz aniversário, Ana!" value={message} onChange={e=>setMessage(e.target.value)}/></div><div className="flex justify-between items-center gap-3"><span className="label">Quantidade</span><div className="flex items-center gap-2 border rounded-full px-2 py-1"><button className="h-11 w-11 grid place-items-center" aria-label="Diminuir" onClick={()=>setQty(Math.max(1,qty-1))}><Minus size={20}/></button><strong className="min-w-7 text-center tabular-nums">{qty}</strong><button className="h-11 w-11 grid place-items-center" aria-label="Aumentar" onClick={()=>setQty(Math.min(99,qty+1))}><Plus size={20}/></button></div></div><Button className="w-full" onClick={()=>onAdd({option_id:selected.id,qty,gift_wrap:wrap,personal_message:message.trim()},product)}><ShoppingBag size={16}/> Adicionar · {money((selected.price_cents+extra)*qty)}</Button></div></section></div>}
function CartDrawer({open,onClose,cart,products,settings,onQty,onRemove,onCheckout,onBrowse}){const rows=cart.map(c=>{const p=products.find(p=>p.options.some(o=>o.id===c.option_id));return {...c,product:p,option:p?.options.find(o=>o.id===c.option_id)}}).filter(x=>x.option);const sub=rows.reduce((s,r)=>s+(r.option.price_cents+(r.gift_wrap?settings.gift_wrap_cents:0))*r.qty,0);const hasItems=rows.length>0&&sub>0;return <><div onClick={onClose} className={`fixed inset-0 z-40 bg-[#241814]/60 transition ${open?'opacity-100':'opacity-0 pointer-events-none'}`}/><aside role="dialog" aria-modal="true" aria-label="Seu carrinho" className={`fixed top-0 right-0 bottom-0 z-50 w-full max-w-[410px] bg-cream shadow-2xl flex flex-col transition-transform duration-300 pb-[env(safe-area-inset-bottom)] ${open?'translate-x-0':'translate-x-full pointer-events-none'}`} aria-hidden={!open}><div className="p-5 flex items-center justify-between border-b border-[#e9d9d2]"><h3 className="font-display text-2xl">Minha encomenda ♡</h3><button onClick={onClose} aria-label="Fechar carrinho" className="rounded-full bg-white border p-2.5 min-w-11 min-h-11 grid place-items-center"><X size={19}/></button></div><div className="flex-1 overflow-y-auto p-5">{rows.length?rows.map(r=><div key={r.line_key||r.option_id} className="flex gap-3 py-4 border-b border-[#efded8]"><img src={r.product.image_url} className="w-20 h-20 object-cover rounded-xl" alt=""/><div className="flex-1 min-w-0"><p className="font-semibold text-sm">{r.product.name}</p><p className="text-taupe text-[11px] mt-1">{r.option.label}{r.gift_wrap?' · Presente':''}</p>{r.mix_label&&<p className="text-[10px] text-taupe">{r.mix_label}</p>}{r.personal_message&&<p className="text-[10px] text-taupe truncate">“{r.personal_message}”</p>}<div className="flex items-center justify-between gap-2 mt-3">{r.option_id==='mixed-custom'?<span className="text-xs text-taupe">{r.qty.toLocaleString('pt-BR')} doces · remova para refazer</span>:<div className="flex gap-2 items-center rounded-full border px-2 py-1"><button type="button" aria-label="Diminuir quantidade" className="min-w-9 min-h-9 grid place-items-center" onClick={()=>onQty(r.line_key||r.option_id,-1)}><Minus size={14}/></button><span className="text-xs font-bold min-w-5 text-center">{r.qty}</span><button type="button" aria-label="Aumentar quantidade" className="min-w-9 min-h-9 grid place-items-center" onClick={()=>onQty(r.line_key||r.option_id,1)}><Plus size={14}/></button></div>}<strong className="text-xs">{money((r.option.price_cents+(r.gift_wrap?settings.gift_wrap_cents:0))*r.qty)}</strong><button type="button" onClick={()=>onRemove(r.line_key||r.option_id)} aria-label="Remover produto" className="min-w-9 min-h-9 grid place-items-center"><Trash2 size={14} className="text-rose"/></button></div></div></div>):<div className="py-20 text-center text-taupe"><ShoppingBag size={42} className="mx-auto opacity-40"/><p className="mt-4 font-semibold">Seu carrinho está vazio</p><p className="text-xs mt-2 mb-5">Escolha suas delícias no cardápio.</p><Button soft className="min-h-12" onClick={()=>{onClose();onBrowse()}}>Ver cardápio <ArrowRight size={16}/></Button></div>}</div><div className="p-5 border-t border-[#eadad2]"><div className="flex justify-between mb-4 font-bold"><span>Subtotal</span><span>{money(sub)}</span></div><Button disabled={!hasItems} className="w-full min-h-12" onClick={()=>{if(!hasItems)return;onClose();onCheckout()}}>Finalizar encomenda <ArrowRight size={16}/></Button><p aria-live="polite" className="text-center mt-3 text-[11px] text-taupe">{hasItems?"Frete e descontos calculados no checkout.":"Adicione pelo menos um doce para continuar."}</p></div></aside></>}
function TrackModal({onClose}){const [code,setCode]=useState(''),[phone,setPhone]=useState(''),[result,setResult]=useState(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[cpf,setCpf]=useState(''),[pix,setPix]=useState(null),[pixBusy,setPixBusy]=useState(false);async function requestPix(){setError('');setPixBusy(true);try{setPix(await requestPixForTrackedOrder(code,phone,cpf))}catch(e){setError(e.message)}finally{setPixBusy(false)}}async function search(e){e.preventDefault();setBusy(true);setError('');try{const {order}=await trackOrder(code,phone);setResult(order)}catch(err){setError(err.message);setResult(null)}finally{setBusy(false)}}return <div className="fixed inset-0 z-50 bg-black/55 grid place-items-center p-3" onClick={onClose}><div className="card max-w-lg w-full p-5 sm:p-7 max-h-[90vh] overflow-y-auto" onClick={e=>e.stopPropagation()}><div className="flex justify-between items-center"><h3 className="font-display text-3xl">Acompanhar pedido</h3><button onClick={onClose}><X/></button></div><p className="text-sm text-taupe mt-2 mb-6">Informe o código recebido e o WhatsApp cadastrado na encomenda. A consulta mostra apenas o andamento do seu pedido.</p><form className="space-y-3" onSubmit={search}><label className="label">Código do pedido</label><input className="field" placeholder="DD-XXXXXXXXXX" value={code} required onChange={e=>{setCode(e.target.value.toUpperCase());setResult(null);setPix(null);setError('')}}/><label className="label">WhatsApp com DDD</label><input className="field" type="tel" placeholder="(11) 99999-9999" value={phone} required onChange={e=>{setPhone(e.target.value);setResult(null);setPix(null);setError('')}}/><Button disabled={busy} className="w-full"><Search size={16}/> {busy?'Buscando...':'Consultar pedido'}</Button></form>{error&&<p role="alert" className="text-sm text-red-700 mt-4">{error}</p>}{result&&<div className="bg-[#f9f0eb] rounded-2xl p-4 mt-5 space-y-3 enter"><p className="eyebrow">Pedido {result.code}</p><h4 className="font-display text-2xl">{statusLabels[result.status]||result.status}</h4><div className="flex gap-1.5">{statusOptions.filter(s=>s!=='cancelado').map((s,i)=><div key={s} className={`h-1.5 rounded-full flex-1 ${statusOptions.indexOf(result.status)>=i?'bg-rose':'bg-[#e2d3cb]'}`}/>)}</div><p className="text-sm">Data solicitada: {dateBR(result.scheduled_at)}</p><p className="text-sm">Pagamento: {result.payment_status==='approved'?'Pix aprovado':result.payment_status==='pending'?'Pix aguardando confirmação':result.payment_status==='deposit_paid'?'Sinal Pix confirmado':'A confirmar'}</p><p className="font-bold">Total: {money(result.total_cents)}</p><p className="text-xs text-taupe">Confirmações e alterações serão informadas pela confeitaria.</p>{result.payment_method==='Pix'&&result.payment_status!=='approved'&&result.payment_status!=='deposit_paid'&&<div className="mt-4 border-t border-[#e5cfc7] pt-4 space-y-2"><p className="font-semibold text-sm">Pagamento por Pix</p><p className="text-xs text-taupe">Solicite o Pix após a Drica confirmar sua encomenda. Se o Mercado Pago não estiver configurado, nenhuma cobrança será gerada.</p><label className="label">CPF para gerar Pix</label><input className="field" inputMode="numeric" maxLength={14} placeholder="Somente números" value={cpf} onChange={e=>setCpf(e.target.value)}/><button disabled={!isLive||pixBusy||digits(cpf).length!==11||result.status==='solicitado'} className="btn-dark w-full" onClick={requestPix}><Wallet size={16}/> {pixBusy?'Consultando...':isLive?'Gerar Pix do pedido confirmado':'Pix real indisponível na demonstração'}</button>{pix&&<div className="space-y-2 rounded-xl bg-white p-3"><p className="text-sm font-semibold">Pix gerado: {money(pix.amount_cents)} · Saldo restante: {money(pix.balance_cents)}</p>{pix.qr_code_base64&&<img className="mx-auto max-w-44" src={'data:image/png;base64,'+pix.qr_code_base64} alt="QR Code Pix"/>}<textarea className="field text-xs" rows={3} readOnly value={pix.qr_code||''}/><button type="button" className="chip" onClick={()=>navigator.clipboard.writeText(pix.qr_code||'')}><Copy size={14}/> Copiar Pix</button></div>}</div>}</div>}</div></div>}
function Checkout({cart,products,settings,zones,blocked,onFinished,onNotify,onBrowse}){const [form,setForm]=useState(emptyForm),[loadingCep,setLoadingCep]=useState(false),[cepError,setCepError]=useState(''),[submitting,setSubmitting]=useState(false),[result,setResult]=useState(null),[pix,setPix]=useState(null),[payBusy,setPayBusy]=useState(false);const set=(k,v)=>setForm(f=>({...f,[k]:v}));const today=localToday();const priced=cart.map(c=>{const p=products.find(p=>p.options.some(o=>o.id===c.option_id));const o=p?.options.find(o=>o.id===c.option_id);return {...c,p,o}}).filter(x=>x.o);const subtotal=priced.reduce((a,c)=>a+(c.o.price_cents+(c.gift_wrap?settings.gift_wrap_cents:0))*c.qty,0);const hasItems=priced.length>0&&subtotal>0;const zone=form.fulfillment==='Entrega'?[...zones].filter(z=>z.active&&digits(form.cep).startsWith(z.cep_prefix)).sort((a,b)=>b.cep_prefix.length-a.cep_prefix.length)[0]:null;const deliveryFee=form.fulfillment==='Retirada'?0:zone?.fee_cents??null;const previewTotal=subtotal+(deliveryFee||0);const isBlocked=blocked.some(b=>b.date===form.scheduled_at.slice(0,10));const checkCep=async()=>{const code=digits(form.cep);if(form.fulfillment!=='Entrega'||code.length!==8)return;setLoadingCep(true);setCepError('');try{const r=await fetch(`https://viacep.com.br/ws/${code}/json/`);if(!r.ok)throw Error('CEP indisponível');const data=await r.json();if(data.erro)throw Error('CEP não encontrado');setForm(f=>({...f,street:data.logradouro||f.street,neighborhood:data.bairro||f.neighborhood,city:data.localidade||f.city,state:data.uf||f.state,cep:code.replace(/^(\d{5})(\d{3})$/,'$1-$2')}))}catch(err){setCepError('Não foi possível consultar o CEP. Preencha manualmente.')}finally{setLoadingCep(false)}};
  useEffect(()=>{if(form.fulfillment!=='Entrega'||digits(form.cep).length!==8)return;const t=setTimeout(checkCep,450);return()=>clearTimeout(t)},[form.cep,form.fulfillment]);
  async function submit(e){e.preventDefault();if(!hasItems)return onNotify('Adicione pelo menos um doce para acessar o pagamento.');if(form.payment_method==='Pix'&&(!/^\S+@\S+\.\S+$/.test(form.email)||digits(form.cpf).length!==11))return onNotify('Para Pix, informe e-mail e CPF com 11 dígitos.');if(form.fulfillment==='Entrega'&&!zone&&!settings.allow_delivery_without_zone)return onNotify('CEP fora da área de entrega cadastrada.');if(isBlocked)return onNotify('Data indisponível. Escolha outra data.');if(!form.scheduled_at||form.scheduled_at.slice(0,10)<today)return onNotify('Selecione uma data válida.');setSubmitting(true);try{const payload={...form,phone:digits(form.phone),cep:digits(form.cep),cpf:undefined,items:cart.map(c=>({...c})),client_request_id:crypto.randomUUID()};const data=await createOrder(payload,{products,settings,zones,blocked,coupons:isLive?[]:(getDemo().coupons||undefined)});setResult({...data.order,access_token:data.access_token||data.order.access_token});onFinished();if(data.isDemo)onNotify('Pedido salvo apenas nesta demonstração. WhatsApp disponível.');else if(!data.emailSent)onNotify('Pedido registrado; aviso por e-mail pode não ter sido entregue.')}catch(err){onNotify(err.message)}finally{setSubmitting(false)}}
  async function generatePix(){if(!result||!result.items?.length)return onNotify("Selecione doces antes de pagar.");setPayBusy(true);try{const r=await payPix(result,form.cpf);setPix(r)}catch(err){onNotify(err.message)}finally{setPayBusy(false)}}
  if(!result&&!hasItems)return <section id="encomendar" className="py-12 sm:py-20 px-4 sm:px-7 scroll-mt-24"><div className="max-w-xl mx-auto card p-7 sm:p-12 text-center enter" role="status"><div className="w-20 h-20 rounded-full bg-blush text-rose mx-auto grid place-items-center"><ShoppingBag size={36}/></div><p className="eyebrow mt-6">Sua encomenda</p><h2 className="font-display text-3xl sm:text-4xl mt-3">Seu carrinho está vazio ♡</h2><p className="text-sm sm:text-base text-taupe leading-7 mt-4">Para escolher data, entrega e forma de pagamento, adicione pelo menos um doce ao carrinho.</p><Button className="w-full sm:w-auto min-h-12 mt-6" onClick={onBrowse}><ShoppingBag size={17}/> Explorar o cardápio <ArrowRight size={17}/></Button><p className="text-xs text-taupe mt-5">Nenhum pedido ou pagamento será criado enquanto o carrinho estiver vazio.</p></div></section>;
  return <section id="encomendar" className="py-16 sm:py-24 scroll-mt-24"><div className="max-w-6xl mx-auto px-4 sm:px-7 grid lg:grid-cols-[.83fr_1.17fr] gap-7 lg:gap-12"><div className="bg-blush rounded-[28px] px-6 py-7 sm:px-9 sm:py-12 self-start order-2 lg:order-1"><div className="eyebrow">✦ Seu momento doce</div><h2 className="h2 mt-3">A alegria chega em <em className="text-rose">forma de doce.</em></h2><p className="text-taupe text-sm leading-7 mt-5">Escolha uma data, informe os detalhes e envie sua solicitação. Nossa equipe confirmará a disponibilidade e os valores de entrega.</p><div className="space-y-4 mt-9 text-sm font-semibold"><p className="flex items-center gap-3"><CheckCircle2 size={19} className="text-rose"/> Feito sob encomenda</p><p className="flex items-center gap-3"><CalendarDays size={19} className="text-rose"/> Escolha seu melhor dia</p><p className="flex items-center gap-3"><MessageCircle size={19} className="text-rose"/> Confirmação pelo WhatsApp</p><p className="flex items-center gap-3"><PackageCheck size={19} className="text-rose"/> Acompanhe cada etapa</p></div><div className="bg-white/70 p-4 rounded-2xl mt-8"><p className="text-xs text-taupe">Precisa de ajuda?</p><a href={`https://wa.me/${WHATSAPP}`} target="_blank" rel="noreferrer" className="font-bold text-sm flex gap-2 items-center mt-1 text-cocoa"><MessageCircle size={16}/> (11) 96081-4357 <ExternalLink size={13}/></a></div></div><div className="card p-5 sm:p-8 min-w-0 order-1 lg:order-2"><h3 className="font-display text-[27px]">{result?'Encomenda solicitada! ♡':'Finalizar encomenda'}</h3>{result?<div className="space-y-4 mt-5 enter"><div className="bg-[#f5e7e4] rounded-2xl p-5"><p className="eyebrow">Guarde o seu código</p><p className="font-display text-3xl mt-2 font-semibold">{result.code}</p><p className="text-xs text-taupe mt-2">Seu pedido foi registrado como solicitado, ainda não confirmado.</p></div><div className="text-sm space-y-2"><p>Subtotal: <strong>{money(result.subtotal_cents)}</strong></p><p>Desconto: {money(result.discount_cents||0)}</p><p>Taxa de entrega: {result.delivery_fee_cents===null?'A confirmar':money(result.delivery_fee_cents||0)}</p><p className="text-xl font-bold">Total{result.delivery_fee_cents===null?' parcial':''}: {money(result.total_cents)}</p></div><a href={prepareWhatsApp(result)} target="_blank" rel="noopener noreferrer" className="btn-dark w-full"><MessageCircle size={17}/> Enviar solicitação ao WhatsApp</a>{result.payment_method==='Pix'&&result.delivery_fee_cents!==null&&<>{pix?<div className="rounded-2xl border p-4 space-y-3"><p className="font-bold text-sm">Pix gerado — aguardando pagamento</p>{pix.qr_code_base64&&<img className="w-48 mx-auto" alt="QR Code Pix" src={'data:image/png;base64,'+pix.qr_code_base64}/>}<textarea className="field text-xs h-24" readOnly value={pix.qr_code||''}/><Button soft className="w-full" onClick={()=>navigator.clipboard?.writeText(pix.qr_code||'')}><Copy size={15}/> Copiar código Pix</Button><p className="text-xs text-taupe">O pagamento só será confirmado após retorno do Mercado Pago.</p></div>:<Button soft disabled={payBusy||!isLive} className="w-full" onClick={generatePix}><Wallet size={17}/> {payBusy?'Aguarde...':isLive?'Gerar Pix com QR Code':'Pix automático indisponível na demonstração'}</Button>}</>}<button className="text-sm underline text-rose font-semibold" onClick={()=>{setResult(null);setPix(null);setForm(emptyForm)}}>Fazer outra encomenda</button></div>:<form onSubmit={submit} className="mt-5 space-y-4"><div className="grid sm:grid-cols-2 gap-4"><label className="sm:col-span-2"><span className="label">Nome completo *</span><input className="field" required minLength={2} maxLength={90} autoComplete="name" value={form.name} onChange={e=>set('name',e.target.value)} placeholder="Como podemos chamar você?"/></label><label><span className="label">WhatsApp com DDD *</span><input className="field" type="tel" required minLength={10} maxLength={20} value={form.phone} onChange={e=>set('phone',e.target.value)} placeholder="(11) 99999-9999"/></label><label><span className="label">E-mail {form.payment_method==='Pix'?'*':'(para notificações)'}</span><input className="field" type="email" required={form.payment_method==='Pix'} value={form.email} onChange={e=>set('email',e.target.value)} placeholder="seuemail@exemplo.com"/></label><label><span className="label">Data desejada *</span><input className="field" required min={today} type="date" value={form.scheduled_at.slice(0,10)} onChange={e=>set('scheduled_at',e.target.value+'T'+(form.scheduled_at.slice(11)||'12:00'))}/></label><label><span className="label">Horário desejado *</span><input className="field" required type="time" min={settings.open_time} max={settings.close_time} value={form.scheduled_at.slice(11)} onChange={e=>set('scheduled_at',(form.scheduled_at.slice(0,10)||today)+'T'+e.target.value)}/></label></div>{isBlocked&&<p className="text-red-700 text-xs">Este dia está bloqueado para novas encomendas.</p>}<p className="text-[11px] text-taupe">Solicite com pelo menos {settings.min_hours}h de antecedência; sujeito à disponibilidade de agenda.</p><div className="grid grid-cols-2 gap-3"><button type="button" onClick={()=>set('fulfillment','Retirada')} className={`rounded-2xl border p-4 text-xs font-bold flex items-center gap-2 ${form.fulfillment==='Retirada'?'border-rose bg-blush':'border-[#ebd9d2]'}`}><Store size={19}/> Retirada</button><button type="button" onClick={()=>set('fulfillment','Entrega')} className={`rounded-2xl border p-4 text-xs font-bold flex items-center gap-2 ${form.fulfillment==='Entrega'?'border-rose bg-blush':'border-[#ebd9d2]'}`}><Truck size={19}/> Entrega</button></div>{form.fulfillment==='Entrega'&&<div className="grid sm:grid-cols-2 gap-3 bg-[#fff9f6] rounded-2xl p-3 sm:p-4"><label><span className="label">CEP *</span><div className="relative"><input className="field" required maxLength={9} inputMode="numeric" value={form.cep} onChange={e=>set('cep',e.target.value)} placeholder="00000-000"/><span className="absolute right-3 top-3 text-[10px] text-rose">{loadingCep?'Buscando...':'ViaCEP'}</span></div></label><label><span className="label">Número *</span><input className="field" required maxLength={15} value={form.number} onChange={e=>set('number',e.target.value)} placeholder="123"/></label><label className="sm:col-span-2"><span className="label">Rua *</span><input className="field" required value={form.street} onChange={e=>set('street',e.target.value)}/></label><label><span className="label">Bairro *</span><input className="field" required value={form.neighborhood} onChange={e=>set('neighborhood',e.target.value)}/></label><label><span className="label">Complemento</span><input className="field" value={form.complement} onChange={e=>set('complement',e.target.value)}/></label><label><span className="label">Cidade *</span><input className="field" required value={form.city} onChange={e=>set('city',e.target.value)}/></label><label><span className="label">UF *</span><input className="field" required maxLength={2} value={form.state} onChange={e=>set('state',e.target.value.toUpperCase())}/></label>{cepError&&<p className="sm:col-span-2 text-xs text-rose">{cepError}</p>}<p className="sm:col-span-2 text-xs text-taupe">{zone?`Taxa para sua região: ${money(zone.fee_cents)}`:settings.allow_delivery_without_zone?'Taxa e disponibilidade serão confirmadas no WhatsApp.':'Fora das áreas de entrega cadastradas.'}</p></div>}<div className="grid sm:grid-cols-2 gap-4"><label><span className="label">Forma de pagamento *</span><select className="field" value={form.payment_method} onChange={e=>set('payment_method',e.target.value)}><option>Cartão no recebimento</option><option>Pix</option></select></label><label><span className="label">Cupom promocional</span><input className="field uppercase" maxLength={24} value={form.coupon} onChange={e=>set('coupon',e.target.value.toUpperCase())} placeholder="SEU CUPOM"/></label></div>{form.payment_method==='Pix'&&<label><span className="label">CPF para pagamento Pix *</span><input className="field" inputMode="numeric" maxLength={14} value={form.cpf} onChange={e=>set('cpf',e.target.value)} placeholder="Apenas números"/><span className="text-[10px] text-taupe">CPF não é armazenado no cadastro da encomenda; é usado para solicitar o Pix ao processador.</span></label>}<label><span className="label">Observações</span><textarea className="field" rows={2} maxLength={350} value={form.notes} onChange={e=>set('notes',e.target.value)} placeholder="Algum detalhe especial?"/></label><div className="border-t border-[#efded8] pt-4 text-sm space-y-2"><div className="flex justify-between text-taupe"><span>{cart.reduce((n,x)=>n+x.qty,0)} itens · Subtotal</span><strong className="text-cocoa">{money(subtotal)}</strong></div><div className="flex justify-between text-taupe"><span>Entrega</span><span>{deliveryFee===null?'A confirmar':money(deliveryFee)}</span></div><div className="flex justify-between font-bold text-lg pt-2"><span>Total {deliveryFee===null?'parcial':''}</span><span>{money(previewTotal)}</span></div>{form.coupon&&<p className="text-[11px] text-rose">O desconto será validado no servidor ao criar o pedido.</p>}</div><Button disabled={!hasItems||submitting} className="w-full min-h-12">{submitting?'Registrando pedido...':'Solicitar encomenda'} <ArrowRight size={16}/></Button><p className="text-[11px] leading-5 text-taupe">A encomenda só será confirmada após resposta da Drica Doces. Os dados informados são usados para preparar e acompanhar a solicitação.</p></form>}</div></div></section>}
function AdminPanel({onClose,onNotify,onCatalogChanged}){const [user,setUser]=useState(null),[login,setLogin]=useState({email:'',password:''}),[showPassword,setShowPassword]=useState(false),[checking,setChecking]=useState(true),[orderSearch,setOrderSearch]=useState(''),[orderFilter,setOrderFilter]=useState('todos'),[tab,setTab]=useState('orders'),[data,setData]=useState(null),[busy,setBusy]=useState(false),[editing,setEditing]=useState(null),[newStatus,setNewStatus]=useState({});
  async function refresh(){try{setData(await adminLoad())}catch(err){onNotify('Painel: '+err.message)}}
  useEffect(()=>{let active=true;(async()=>{try{if(!isLive){if(active){setUser(null);setData(null)}return;}const u=await getAdminUser();if(active){setUser(u);if(u)await refresh()}}catch(err){onNotify(err.message)}finally{if(active)setChecking(false)}})();return()=>{active=false}},[]);
  async function authenticate(e){e.preventDefault();if(!isLive){onNotify('O painel restrito exige Supabase Auth configurado.');return;}setBusy(true);try{await signIn(login.email,login.password);const u=await getAdminUser();if(!u){await signOut();throw Error('Este usuário não tem permissão de administrador.')}setUser(u);await refresh();setLogin({email:'',password:''})}catch(err){onNotify(err.message)}finally{setBusy(false)}}
  async function save(table,entry,idColumn='id'){setBusy(true);try{await adminSave(table,entry,idColumn);await refresh();setEditing(null);onCatalogChanged();onNotify('Alterações salvas.')}catch(err){onNotify('Erro ao salvar: '+err.message)}finally{setBusy(false)}}
  async function remove(table,id){if(!confirm('Confirma a exclusão deste registro?'))return;setBusy(true);try{await adminDelete(table,id);await refresh();onCatalogChanged();onNotify('Registro excluído.')}catch(err){onNotify(err.message)}finally{setBusy(false)}}
  async function changeStatus(orderId,status){setBusy(true);try{const r=await adminStatus(orderId,status);await refresh();onNotify(r.emailSent?'Status e notificação por e-mail atualizados.':'Status atualizado. Notificação automática não confirmada.')}catch(err){onNotify(err.message)}finally{setBusy(false)}}
  if(checking)return <div className="fixed inset-0 z-50 bg-cream grid place-items-center">Carregando painel...</div>;
  const orders=data?.orders||[];const settings=data?.settings||demoSettings;
  const visibleOrders=orders.filter(o=>(orderFilter==='todos'||o.status===orderFilter)&&(!orderSearch.trim()||[o.code,o.customer_name].some(v=>String(v||'').toLocaleLowerCase('pt-BR').includes(orderSearch.trim().toLocaleLowerCase('pt-BR')))));
  return <div className="fixed inset-0 z-[55] bg-[#fffaf7] overflow-y-auto"><header className="sticky top-0 z-10 bg-cream border-b border-[#ecdcd5] px-4 sm:px-8 py-4"><div className="max-w-7xl mx-auto flex items-center justify-between gap-3"><div className="flex gap-3 items-center"><div className="bg-blush rounded-xl p-2"><LayoutDashboard size={21}/></div><div><strong className="font-display text-xl">Drica Doces</strong><p className="text-[10px] uppercase tracking-widest text-taupe">Painel administrativo</p></div></div><div className="flex gap-2 items-center">{user&&<button className="chip" onClick={async()=>{await signOut();setUser(null);setData(null)}}><LogOut size={14}/> Sair</button>}<button className="chip" onClick={onClose}><X size={15}/> Fechar</button></div></div></header>{!user?<main className="max-w-sm mx-auto px-5 py-16"><div className="card p-7"><Lock size={28} className="text-rose"/><h2 className="font-display text-3xl mt-4">Acesso restrito</h2><p className="text-taupe text-sm my-4">Área exclusiva da equipe autorizada. Clientes não podem acessar pedidos ou dados de outras pessoas.</p>{!isLive?<div className="rounded-xl border border-[#e9c5bb] bg-[#fff3eb] p-4 text-sm text-[#7c4a3c] mb-5" role="status"><strong>Administração bloqueada na demonstração.</strong><p className="mt-2 text-xs leading-5">Para habilitar usuário e senha com segurança, publique o projeto com Supabase Auth, cadastre a conta da administração e autorize-a em admin_users. Não existe senha padrão.</p></div>:<form onSubmit={authenticate} className="space-y-3"><label className="label" htmlFor="admin-login-email">Usuário (e-mail de acesso)</label><input id="admin-login-email" className="field" type="email" autoComplete="username" required value={login.email} onChange={e=>setLogin({...login,email:e.target.value})}/><label className="label" htmlFor="admin-login-pass">Senha</label><div className="relative"><input id="admin-login-pass" className="field !pr-16" type={showPassword?'text':'password'} autoComplete="current-password" required minLength={6} value={login.password} onChange={e=>setLogin({...login,password:e.target.value})}/><button type="button" className="absolute right-3 top-1/2 -translate-y-1/2 text-rose font-bold text-xs min-h-10 px-2" onClick={()=>setShowPassword(v=>!v)} aria-label={showPassword?'Ocultar senha':'Mostrar senha'}>{showPassword?'Ocultar':'Mostrar'}</button></div><Button disabled={busy} className="w-full">{busy?'Autenticando...':'Entrar com segurança'}</Button></form>}</div></main>:<main className="max-w-7xl mx-auto px-4 sm:px-7 py-6 sm:py-9"><div className="flex gap-2 overflow-x-auto overscroll-x-contain snap-x snap-mandatory pb-3 mb-6 -mx-4 px-4 sm:mx-0 sm:px-0" aria-label="Seções administrativas">{[['orders','Pedidos',ClipboardList],['agenda','Agenda',CalendarDays],['production','Produção',PackageCheck],['inventory','Estoque',Package],['finance','Financeiro',Wallet],['products','Produtos',CakeSlice],['coupons','Cupons',Ticket],['zones','Entrega',Truck],['blocked','Datas bloqueadas',CalendarDays],['settings','Configurações',SettingsIcon]].map(([id,name,Icon])=><button key={id} className={`chip shrink-0 snap-start min-h-12 ${tab===id?'!bg-cocoa !text-white':''}`} onClick={()=>{setTab(id);setEditing(null)}}><Icon size={14}/>{name}</button>)}</div>
    {tab==='orders'&&<><div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">{[['Solicitados',orders.filter(o=>o.status==='solicitado').length,Clock],['Em preparo',orders.filter(o=>o.status==='preparando').length,CakeSlice],['Entregues',orders.filter(o=>o.status==='entregue').length,PackageCheck],['Total pedido',money(orders.filter(o=>o.status!=='cancelado').reduce((s,o)=>s+(o.total_cents||0),0)),Wallet]].map(([label,val,Icon])=><div className="card p-4" key={label}><Icon className="text-rose mb-2" size={20}/><p className="text-xs text-taupe">{label}</p><h3 className="font-display text-2xl mt-1">{val}</h3></div>)}</div><h3 className="font-display text-2xl mb-4">Encomendas recebidas</h3><div className="grid sm:grid-cols-2 gap-3 mb-4"><label className="block"><span className="label">Buscar por código ou cliente</span><input className="field" type="search" value={orderSearch} onChange={e=>setOrderSearch(e.target.value)} placeholder="Buscar encomenda"/></label><label className="block"><span className="label">Filtrar andamento</span><select className="field" value={orderFilter} onChange={e=>setOrderFilter(e.target.value)}><option value="todos">Todos os status</option>{statusOptions.map(st=><option key={st} value={st}>{statusLabels[st]}</option>)}</select></label></div><p className="text-xs text-taupe mb-3">{visibleOrders.length} encomenda(s) encontradas · dados disponíveis apenas para administradores autorizados.</p>{orders.length? <div className="grid lg:grid-cols-2 gap-3">{visibleOrders.map(o=><div key={o.id} className="card p-4 sm:p-5 space-y-3"><div className="flex flex-wrap justify-between gap-2"><div><strong className="text-sm">{o.code}</strong><p className="text-xs text-taupe mt-1">{o.customer_name} · {o.customer_phone}</p></div><span className="bg-blush text-rose px-3 py-1 rounded-full text-xs font-bold h-fit">{statusLabels[o.status]}</span></div><p className="text-xs">{dateBR(o.scheduled_at)} · {o.fulfillment}</p><p className="text-xs text-taupe">{o.address||'Retirada'}</p><div className="border-y py-2 border-[#eee0da] text-xs space-y-1">{(o.order_items||o.items||[]).map((r,i)=><p key={i}>{r.qty} × {r.product_name||r.name} ({r.option_label})</p>)}</div><div className="flex justify-between text-sm"><strong>{money(o.total_cents)}</strong><span className="text-taupe">Pix: {o.payment_status==='approved'?'Aprovado':o.payment_status==='pending'?'Pendente':'Não pago/sem cobrança'}</span></div><div className="flex gap-2"><select className="field flex-1" aria-label="Alterar status do pedido" disabled={busy} value={newStatus[o.id]||o.status} onChange={e=>setNewStatus(s=>({...s,[o.id]:e.target.value}))}>{statusOptions.map(s=><option key={s} value={s}>{statusLabels[s]}</option>)}</select><button className="btn-dark !px-3" disabled={busy||(newStatus[o.id]||o.status)===o.status} onClick={()=>changeStatus(o.id,newStatus[o.id])}><Save size={16}/></button></div><a className="chip !py-2" target="_blank" rel="noreferrer" href={`https://wa.me/55${digits(o.customer_phone)}?text=${encodeURIComponent(`Olá, ${o.customer_name}! Sua encomenda ${o.code} na Drica Doces está: ${statusLabels[o.status]}.`)}`}><MessageCircle size={14}/> Conversar com cliente</a></div>)}</div>:<div className="card p-12 text-center text-taupe">Nenhuma encomenda recebida ainda.</div>}</>}
    {tab==='agenda'&&<AgendaPanel orders={orders} settings={settings}/>}
    {tab==='production'&&<ProductionPanel orders={orders} checks={data?.productionChecks||[]} busy={busy} onSave={entry=>save('production_checks',entry)}/>}
    {tab==='inventory'&&<InventoryPanel items={data?.inventory||[]} busy={busy} onSave={entry=>save('inventory_items',entry)} onRemove={id=>remove('inventory_items',id)}/>}
    {tab==='finance'&&<FinancePanel orders={orders} payments={data?.payments||[]} settings={settings} notifications={data?.notifications||[]}/>}
    {tab==='products'&&<><div className="flex justify-between items-center mb-4"><h3 className="font-display text-2xl">Cardápio</h3><Button className="!py-2" onClick={()=>setEditing({type:'products',value:{name:'',category:'Brigadeiros',description:'',image_url:'',tag:'Artesanal',active:true,options:[{id:'produto-'+crypto.randomUUID().slice(0,8),label:'Unidade',price_cents:0}]}})}><Plus size={15}/> Novo doce</Button></div><div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">{(data?.products||[]).map(p=><div key={p.id} className="card p-4 flex gap-3"><img src={p.image_url||'/favicon.svg'} className="w-20 h-20 rounded-xl object-cover" alt=""/><div className="flex-1"><p className="font-semibold text-sm">{p.name}</p><p className="text-xs text-taupe mt-1">{p.active?'Ativo':'Oculto'} · {p.options?.map(o=>money(o.price_cents)).join(' / ')}</p><button className="text-rose underline text-xs mt-3" onClick={()=>setEditing({type:'products',value:structuredClone(p)})}>Editar produto</button></div></div>)}</div></>}
    {tab==='coupons'&&<><div className="flex justify-between items-center mb-4"><h3 className="font-display text-2xl">Cupons de desconto</h3><Button className="!py-2" onClick={()=>setEditing({type:'coupons',value:{code:'',percent_off:10,min_cents:0,max_uses:100,used_count:0,active:true}})}><Plus size={15}/> Cupom</Button></div><div className="grid sm:grid-cols-2 md:grid-cols-3 gap-3">{(data?.coupons||[]).map(c=><div className="card p-4" key={c.code}><p className="font-bold">{c.code}</p><p className="text-sm text-taupe">{c.percent_off}% desconto · Mín. {money(c.min_cents)}</p><p className="text-xs text-taupe mt-1">{c.used_count||0}/{c.max_uses} usos</p><button className="text-rose underline text-xs mt-3" onClick={()=>setEditing({type:'coupons',value:{...c}})}>Editar cupom</button></div>)}</div></>}
    {tab==='zones'&&<><div className="flex justify-between items-center mb-4"><h3 className="font-display text-2xl">Regiões de entrega</h3><Button className="!py-2" onClick={()=>setEditing({type:'zones',value:{cep_prefix:'',name:'',fee_cents:0,active:true}})}><Plus size={15}/> Região</Button></div><p className="text-xs text-taupe mb-4">Cadastre prefixos de CEP (3 a 8 dígitos). A região com o prefixo mais específico tem prioridade.</p><div className="grid sm:grid-cols-2 md:grid-cols-3 gap-3">{(data?.zones||[]).map(z=><div className="card p-4" key={z.id}><p className="font-bold">{z.name}</p><p className="text-sm">CEP {z.cep_prefix}… · {money(z.fee_cents)}</p><div className="flex gap-3 mt-3"><button className="text-rose underline text-xs" onClick={()=>setEditing({type:'zones',value:{...z}})}>Editar</button><button className="text-red-700 underline text-xs" onClick={()=>remove('delivery_zones',z.id)}>Excluir</button></div></div>)}</div></>}
    {tab==='blocked'&&<><div className="flex justify-between items-center mb-4"><h3 className="font-display text-2xl">Dias indisponíveis</h3><Button className="!py-2" onClick={()=>setEditing({type:'blocked',value:{date:'',reason:'Indisponível'}})}><Plus size={15}/> Bloquear dia</Button></div><div className="grid sm:grid-cols-2 md:grid-cols-3 gap-3">{(data?.blocked||[]).map(b=><div key={b.id} className="card p-4 flex justify-between items-start"><div><p className="font-bold">{dateBR(b.date)}</p><p className="text-xs text-taupe">{b.reason}</p></div><button className="text-red-700 text-xs underline" onClick={()=>remove('blocked_dates',b.id)}>Remover</button></div>)}</div></>}
    {tab==='settings'&&<SettingsForm settings={settings} save={value=>save('shop_settings',{id:1,...value})} busy={busy}/>}
    {editing&&<EditModal edit={editing} busy={busy} close={()=>setEditing(null)} save={async value=>{if(editing.type==='products')await save('products',value);if(editing.type==='coupons')await save('coupons',value,'code');if(editing.type==='zones')await save('delivery_zones',value);if(editing.type==='blocked')await save('blocked_dates',value)}}/>}
  </main>}</div>}
function SettingsForm({settings,save,busy}){const [s,setS]=useState(settings);useEffect(()=>setS(settings),[settings]);function change(k,v){setS(p=>({...p,[k]:v}))}return <div className="max-w-2xl card p-5 sm:p-7"><h3 className="font-display text-2xl mb-5">Configurações da loja</h3><form className="grid sm:grid-cols-2 gap-4" onSubmit={e=>{e.preventDefault();save({...s,min_hours:asInt(s.min_hours),max_orders_per_slot:Math.max(1,asInt(s.max_orders_per_slot)),daily_capacity_sweets:Math.max(50,Math.min(100000,asInt(s.daily_capacity_sweets))),deposit_percent:Math.max(0,Math.min(100,asInt(s.deposit_percent))),gift_wrap_cents:Math.round(Number(s.gift_wrap_cents)||0),loyalty_threshold:Math.max(1,asInt(s.loyalty_threshold)),loyalty_percent:Math.min(100,asInt(s.loyalty_percent))})}}>{[['min_hours','Antecedência mínima (horas)','number'],['max_orders_per_slot','Máximo de pedidos por horário','number'],['daily_capacity_sweets','Capacidade diária (docinhos)','number'],['deposit_percent','Sinal Pix após confirmação (%) · 0 desativa','number'],['open_time','Início do atendimento','time'],['close_time','Fim do atendimento','time'],['gift_wrap_cents','Presente (centavos/item)','number'],['loyalty_threshold','Pedidos para fidelidade','number'],['loyalty_percent','Desconto fidelidade (%)','number'],['business_hours','Horário / texto de atendimento','text'],['instagram_url','Link Instagram','url'],['delivery_notice','Texto de entrega','text']].map(([k,label,type])=><label key={k}><span className="label">{label}</span><input className="field" type={type} value={s[k]??''} onChange={e=>change(k,e.target.value)}/></label>)}<p className="sm:col-span-2 rounded-xl bg-[#fff3e8] p-3 text-xs leading-5 text-taupe">Sinal acima de 0% somente poderá ser solicitado via Pix após confirmação do pedido. Pedidos de entrega exigem uma região com taxa de frete cadastrada. CEPs sem taxa são direcionados ao WhatsApp para cotação antes de registrar ou cobrar.</p><Button disabled={busy} className="sm:col-span-2"><Save size={15}/> Salvar configurações</Button></form></div>}
function EditModal({edit,close,save,busy}){const [v,setV]=useState(edit.value);function change(k,val){setV(s=>({...s,[k]:val}))}const name={products:'Produto',coupons:'Cupom',zones:'Região de entrega',blocked:'Bloqueio de agenda'}[edit.type];function input(k,title,type='text',required=false){return <label key={k}><span className="label">{title}</span><input type={type} className="field" required={required} value={v[k]??''} onChange={e=>change(k,e.target.value)}/></label>}
  function saveChanges(e){e.preventDefault();let val={...v};if(edit.type==='products'){if(!val.name?.trim()||!val.options?.length)return;val.options=val.options.map(o=>({...o,price_cents:asInt(o.price_cents)}))}if(edit.type==='zones'){val.cep_prefix=digits(val.cep_prefix);val.fee_cents=asInt(val.fee_cents);if(val.cep_prefix.length<3||val.cep_prefix.length>8)return alert('Prefixo de CEP deve conter 3 a 8 dígitos.')}if(edit.type==='coupons'){val.code=val.code.toUpperCase().trim();val.percent_off=Math.min(100,asInt(val.percent_off));val.min_cents=asInt(val.min_cents);val.max_uses=Math.max(1,asInt(val.max_uses))}save(val)}
  return <div className="fixed inset-0 z-[65] bg-black/60 grid place-items-center p-3" onClick={close}><div className="card p-5 sm:p-7 w-full max-w-lg max-h-[90vh] overflow-y-auto" onClick={e=>e.stopPropagation()}><div className="flex justify-between items-center mb-5"><h3 className="font-display text-2xl">Editar {name}</h3><button onClick={close}><X size={20}/></button></div><form className="space-y-4" onSubmit={saveChanges}>{edit.type==='products'&&<>{input('name','Nome', 'text',true)}{input('category','Categoria','text',true)}<label><span className="label">Descrição</span><textarea className="field" value={v.description||''} onChange={e=>change('description',e.target.value)}/></label>{input('image_url','URL da foto (https://)')}{input('tag','Selo do produto')}<label className="flex gap-2 text-sm items-center"><input type="checkbox" checked={!!v.active} onChange={e=>change('active',e.target.checked)}/> Produto ativo</label><div className="rounded-xl bg-[#f9eee9] p-3 space-y-3"><p className="text-xs font-bold">Opções de venda (valores em centavos)</p>{v.options.map((o,i)=><div className="grid grid-cols-[1fr_105px_28px] gap-2" key={o.id}><input className="field !px-2" value={o.label} aria-label="Nome da opção" onChange={e=>change('options',v.options.map((x,j)=>i===j?{...x,label:e.target.value}:x))}/><input className="field !px-2" type="number" min="0" value={o.price_cents} aria-label="Preço em centavos" onChange={e=>change('options',v.options.map((x,j)=>i===j?{...x,price_cents:e.target.value}:x))}/><button type="button" onClick={()=>change('options',v.options.filter((_,j)=>j!==i))} aria-label="Excluir variação"><Trash2 size={16}/></button></div>)}<button className="chip" type="button" onClick={()=>change('options',[...v.options,{id:'opt-'+crypto.randomUUID().slice(0,10),label:'Nova opção',price_cents:0}])}><Plus size={14}/> Adicionar opção</button></div></>}{edit.type==='coupons'&&<>{input('code','Código do cupom','text',true)}{input('percent_off','Desconto (%)','number',true)}{input('min_cents','Compra mínima (centavos)','number',true)}{input('max_uses','Limite de utilizações','number',true)}<label className="flex gap-2 items-center text-sm"><input type="checkbox" checked={!!v.active} onChange={e=>change('active',e.target.checked)}/> Ativo</label></>}{edit.type==='zones'&&<>{input('name','Bairro / Região','text',true)}{input('cep_prefix','Prefixo do CEP (3 a 8 números)','text',true)}{input('fee_cents','Taxa de entrega em centavos','number',true)}<label className="flex gap-2 text-sm items-center"><input type="checkbox" checked={!!v.active} onChange={e=>change('active',e.target.checked)}/> Região ativa</label></>}{edit.type==='blocked'&&<>{input('date','Data indisponível','date',true)}{input('reason','Motivo','text',true)}</>}<Button disabled={busy} className="w-full"><Save size={16}/> {busy?'Salvando...':'Salvar'}</Button></form></div></div>}
export default function App(){const [catalog,setCatalog]=useState({products:demoProducts,settings:demoSettings,zones:[],blocked:[]});const [category,setCategory]=useState('Todos'),[modalProduct,setModalProduct]=useState(null),[cart,setCart]=useState(()=>{try{const saved=JSON.parse(localStorage.getItem('drica-cart-v39')||'[]');return Array.isArray(saved)?saved.filter(x=>x&&typeof x.option_id==='string'&&Number.isFinite(x.qty)&&x.qty>0).map(x=>({...x,qty:x.option_id==='mixed-custom'?Math.min(100000,Math.floor(x.qty)):Math.min(99,Math.floor(x.qty))})):[]}catch{return[]}}),[drawer,setDrawer]=useState(false),[track,setTrack]=useState(false),[admin,setAdmin]=useState(false),[menu,setMenu]=useState(false),[toast,setToast]=useState(''),[builderVersion,setBuilderVersion]=useState(0),[largeQuote,setLargeQuote]=useState(null);const flash=msg=>{setToast(msg);setTimeout(()=>setToast(''),3500)};async function refresh(){try{setCatalog(await getCatalog())}catch(err){flash('Não foi possível carregar o cardápio: '+err.message)}}useEffect(()=>{refresh()},[]);useEffect(()=>{try{localStorage.setItem('drica-cart-v39',JSON.stringify(cart))}catch{}},[cart]);function clearCartAfterWhatsApp(){try{localStorage.setItem('drica-cart-v39','[]');localStorage.removeItem('drica-cart-v2')}catch{}setCart([]);setDrawer(false);setModalProduct(null);setBuilderVersion(v=>v+1)};
useEffect(()=>{try{localStorage.removeItem('drica-cart-v2')}catch{}},[]);
useEffect(()=>{const onReturn=()=>{try{if(sessionStorage.getItem('drica-wpp-handoff-v39')==='1'){clearCartAfterWhatsApp()}}catch{}};window.addEventListener('pageshow',onReturn);return()=>window.removeEventListener('pageshow',onReturn)},[]);const cartDetails=(entries)=>entries.map(c=>{const option=catalog.products.flatMap(p=>p.options||[]).find(o=>o.id===c.option_id);const product=catalog.products.find(p=>(p.options||[]).some(o=>o.id===c.option_id));return {...c,name:product?.name||'Docinhos',unit:option?.price_cents||0}});
const quoteFrom=(entries)=>{const detail=cartDetails(entries);setLargeQuote({quantity:detail.reduce((n,i)=>n+(i.option_id==='mixed-custom'?i.qty:i.option_id==='mixed-half'?50*i.qty:100*i.qty),0),description:detail.map(i=>i.mix_label||`${i.qty} × ${i.name}`).join(' | ')});};
const cartCost=(entries)=>cartDetails(entries).reduce((n,i)=>n+i.qty*i.unit,0);const cartSweetCount=(entries)=>entries.reduce((n,i)=>n+(i.option_id==='mixed-custom'?i.qty:i.option_id==='mixed-half'?50*i.qty:100*i.qty),0);
function addItem(entry){if(cartSweetCount([...cart,entry])>500){quoteFrom([...cart,entry]);setModalProduct(null);setDrawer(false);return;}setCart(prev=>{const mixKey=entry.mix_breakdown?`|${JSON.stringify(Object.entries(entry.mix_breakdown).sort(([a],[b])=>a.localeCompare(b)))}`:'';const line_key=entry.option_id==='mixed-custom'?'mixed-custom|'+(crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`):entry.option_id+'|'+String(entry.gift_wrap)+'|'+(entry.personal_message||'')+mixKey;entry={...entry,line_key};const idx=entry.option_id==='mixed-custom'?-1:prev.findIndex(x=>x.line_key===line_key);if(idx>=0)return prev.map((x,i)=>i===idx?{...x,qty:Math.min(99,x.qty+entry.qty)}:x);return[...prev,entry]});setModalProduct(null);flash('Seu doce foi adicionado ♡')};function qty(id,delta){const next=cart.map(x=>(x.line_key||x.option_id)===id&&x.option_id!=='mixed-custom'?{...x,qty:Math.max(0,Math.min(99,x.qty+delta))}:x).filter(x=>x.qty>0);if(cartSweetCount(next)>500){quoteFrom(next);setDrawer(false);return;}setCart(next)};const count=cart.reduce((s,r)=>s+r.qty,0);const rows=catalog.products.filter(p=>p.active&&p.id!=='cento-misto'&&!p.hidden_from_grid&&(category==='Todos'||category===p.category));const go=id=>{setMenu(false);if(id==='encomendar'&&cartSweetCount(cart)>500){quoteFrom(cart);return;}if(id==='encomendar'&&!cart.some(c=>c.qty>0&&catalog.products.some(p=>p.options.some(o=>o.id===c.option_id&&o.price_cents>0)))){flash('Escolha pelo menos um doce antes de finalizar.');id='cardapio'}document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})};useEffect(()=>{if(!drawer)return;const onKey=e=>{if(e.key==='Escape')setDrawer(false)};document.addEventListener('keydown',onKey);return()=>document.removeEventListener('keydown',onKey)},[drawer]);return <div className="min-h-screen bg-cream overflow-x-hidden pb-20 md:pb-0"><div className="bg-[#f2dedb] text-center py-2.5 px-3 text-[10px] font-bold tracking-[.17em] text-[#9f6871] uppercase">✦ Doces feitos com amor para os seus melhores momentos ✦</div><header className="bg-cream/95 backdrop-blur border-b border-[#eee2db] sticky top-0 z-30"><div className="max-w-6xl mx-auto px-4 sm:px-7 flex items-center justify-between gap-3 h-[76px]"><button onClick={()=>go('inicio')} aria-label="Ir ao início"><Logo/></button><nav className="hidden md:flex items-center gap-7 text-[13px] font-semibold text-[#6e5750]"><button onClick={()=>go('inicio')} className="hover:text-rose">Início</button><button onClick={()=>go('cardapio')} className="hover:text-rose">Cardápio</button><button onClick={()=>go('encantar')} className="hover:text-rose">Sobre nós</button><button onClick={()=>go('encomendar')} className="hover:text-rose">Encomendar</button><button onClick={()=>setTrack(true)} className="hover:text-rose">Meu pedido</button></nav><div className="flex gap-2"><button onClick={()=>setDrawer(true)} className="btn-soft !py-2.5 !px-3.5 relative"><ShoppingBag size={17}/><span className="text-xs hidden sm:inline">Carrinho</span><span className="text-[11px] rounded-full px-1.5 py-0.5 bg-rose text-white">{count}</span></button><button className="md:hidden rounded-full border p-2.5 min-w-11 min-h-11 grid place-items-center" aria-label="Menu" onClick={()=>setMenu(!menu)}>{menu?<X size={20}/>:<Menu size={20}/>}</button></div></div>{menu&&<nav className="md:hidden px-6 pb-5 flex flex-col gap-4 text-sm font-semibold">{[['inicio','Início'],['cardapio','Cardápio'],['encantar','Sobre nós'],['encomendar','Encomendar']].map(([id,t])=><button className="text-left min-h-11 flex items-center" key={id} onClick={()=>go(id)}>{t}</button>)}<button className="text-left min-h-11" onClick={()=>{setMenu(false);setTrack(true)}}>Acompanhar pedido</button></nav>}</header>
    <section id="inicio" className="bg-[radial-gradient(ellipse_at_top_left,#f9e5e4_0%,#fffbf7_60%)]"><div className="max-w-6xl mx-auto px-4 sm:px-7 py-12 sm:py-20 grid md:grid-cols-2 items-center gap-8 sm:gap-14"><div className="enter"><p className="eyebrow">✦ Confeitaria artesanal</p><h1 className="font-display text-[49px] sm:text-[68px] xl:text-[77px] leading-[1.08] tracking-[-.045em] mt-5">Cada doce,<br/>um motivo para <em className="text-rose">celebrar.</em></h1><p className="max-w-md text-taupe text-sm sm:text-base leading-8 mt-5">Brigadeiro, beijinho e bicho de pé preparados com carinho para aniversários, festas e momentos especiais.</p><div className="flex gap-3 flex-wrap mt-7"><Button onClick={()=>go('cardapio')}>Ver cardápio <ArrowRight size={17}/></Button><Button soft onClick={()=>setTrack(true)}><Package size={16}/> Acompanhar pedido</Button></div><div className="flex flex-wrap gap-4 text-[11px] font-bold text-taupe mt-8"><span className="flex items-center gap-1"><Heart size={14} className="text-rose"/> Feito com carinho</span><span className="flex items-center gap-1"><Sparkles size={14} className="text-rose"/> Docinhos de festa</span><span className="flex items-center gap-1"><CalendarDays size={14} className="text-rose"/> Sob encomenda</span></div></div><div className="relative max-w-[520px] mx-auto w-full"><div className="rounded-[42%_42%_32%_32%] overflow-hidden h-[300px] sm:h-[470px] bg-[#e9d3ca] rotate-[3deg] shadow-soft"><img src="https://upload.wikimedia.org/wikipedia/commons/a/a4/Brigadeiro.jpg" onError={e=>{e.currentTarget.onerror=null;e.currentTarget.src='/docinhos-festa.jpg'}} className="w-full h-full object-cover object-center -rotate-[3deg] scale-110" alt="Brigadeiro tradicional com granulado de chocolate em forminha dourada — foto ilustrativa" loading="eager"/></div><div className="absolute -bottom-5 left-0 sm:-left-6 bg-white shadow-soft rounded-2xl px-6 py-4 font-display text-xl -rotate-[4deg]">♡ Feitos para encantar</div><div className="absolute -top-2 -right-1 rounded-full w-16 h-16 grid place-items-center bg-[#f5dada] text-rose"><Sparkles size={26}/></div></div></div></section>
    <section className="border-y border-[#eee2dc] bg-white"><div className="max-w-6xl mx-auto px-4 sm:px-7 py-6 grid sm:grid-cols-3 gap-5 text-center"><div className="flex justify-center items-center gap-3"><Heart className="text-rose" size={19}/><span className="text-xs font-semibold">Receitas feitas com carinho</span></div><div className="flex justify-center items-center gap-3"><Gift className="text-rose" size={19}/><span className="text-xs font-semibold">Presentes e festas especiais</span></div><div className="flex justify-center items-center gap-3"><MessageCircle className="text-rose" size={19}/><span className="text-xs font-semibold">Encomendas via WhatsApp</span></div></div></section>
    <section id="cardapio" className="max-w-6xl mx-auto px-4 sm:px-7 py-16 sm:py-24"><SectionHeader eyebrow="Nosso cardápio" title="Pequenos doces." accent="Grandes momentos." description="Escolha o seu doce, veja o valor e toque na imagem para abrir o popup com as informações do produto."/><div className="flex justify-center flex-wrap gap-2 mb-9">{['Todos','Docinhos de festa'].map(k=><button key={k} className={`chip ${category===k?'!bg-cocoa !text-white':''}`} onClick={()=>setCategory(k)}>{k}</button>)}</div><div className="grid grid-cols-1 min-[360px]:grid-cols-2 lg:grid-cols-3 gap-3 sm:gap-5">{rows.map(p=><ProductCard key={p.id} product={p} onSelect={setModalProduct}/>)}</div><p className="text-xs text-taupe text-center mt-6">Toque na imagem de cada doce para abrir o popup com as informações. Os outros produtos foram removidos do cardápio.</p><MixedSweetBuilder key={builderVersion} products={catalog.products} onAdd={addItem} onQuote={setLargeQuote}/></section>
    <section id="encantar" className="bg-[#f8ece8] py-16 sm:py-20"><div className="max-w-6xl mx-auto px-4 sm:px-7"><SectionHeader eyebrow="O carinho que faz diferença" title="Doce é ainda melhor quando" accent="vira lembrança." description="Uma experiência feita de detalhes — da primeira escolha até o último pedacinho."/><div className="grid md:grid-cols-3 gap-4">{[[Heart,'Sabor de carinho','Receitas pensadas para deixar cada celebração mais gostosa.'],[Gift,'Capricho nos detalhes','Escolha apresentação e adicione uma mensagem especial.'],[Star,'Sua opinião importa','Este espaço receberá avaliações reais e autorizadas das nossas clientes.']].map(([Icon,title,desc])=><div key={title} className="card p-7"><div className="w-11 h-11 grid place-items-center bg-blush rounded-full text-rose mb-5"><Icon size={22}/></div><h3 className="font-display text-2xl">{title}</h3><p className="text-taupe text-sm leading-7 mt-3">{desc}</p></div>)}</div></div></section>
    <section className="max-w-6xl mx-auto px-4 sm:px-7 py-16 sm:py-20"><SectionHeader eyebrow="Simples de encomendar" title="Seu doce favorito em" accent="3 passos."/><div className="grid sm:grid-cols-3 gap-5">{[[ShoppingBag,'01','Escolha seus doces','Adicione sabores e quantidades ao carrinho.'],[CalendarDays,'02','Escolha data e entrega','Use o CEP e selecione a data disponível.'],[MessageCircle,'03','Finalize com carinho','Receba um código e conclua pelo WhatsApp.']].map(([Icon,num,title,sub])=><div key={num} className="text-center"><div className="w-16 h-16 mx-auto rounded-full bg-blush grid place-items-center text-rose"><Icon size={27}/></div><p className="eyebrow mt-4">Passo {num}</p><h3 className="font-display text-2xl mt-2">{title}</h3><p className="text-taupe text-sm mt-2">{sub}</p></div>)}</div></section>
    <GuidedCheckout cart={cart} products={catalog.products} settings={catalog.settings} zones={catalog.zones} blocked={catalog.blocked} onFinished={clearCartAfterWhatsApp} onNotify={flash} onBrowse={()=>go("cardapio")} onEditCart={()=>setDrawer(true)} onLargeOrder={()=>quoteFrom(cart)} onChangeQty={qty} onRemove={id=>setCart(p=>p.filter(x=>(x.line_key||x.option_id)!==id))}/>
    <section className="bg-blush py-10"><div className="max-w-6xl mx-auto px-5 flex items-center flex-col sm:flex-row justify-between gap-5"><div><p className="eyebrow">✦ Clube Drica</p><h3 className="font-display text-3xl mt-2">Quem ama doce merece carinho em dobro.</h3><p className="text-sm text-taupe mt-2">Cupons promocionais e benefícios de fidelidade para clientes que voltam.</p></div><Button onClick={()=>go('cardapio')}>Escolher meus doces <ArrowRight size={17}/></Button></div></section>
    <footer className="bg-cocoa text-white px-5 py-12"><div className="max-w-6xl mx-auto grid md:grid-cols-3 gap-7"><div><p className="font-display text-3xl">♡ drica doces.</p><p className="mt-3 text-[#d8bfba] text-xs leading-6">Confeitaria artesanal. Carinho em cada detalhe, doçura em cada mordida.</p></div><div><p className="font-semibold text-sm mb-3">Atendimento</p><p className="text-[#d8bfba] text-xs leading-6">{catalog.settings.business_hours||'Sob encomenda'}<br/>{catalog.settings.delivery_notice||'Retirada ou entrega sob consulta'}</p></div><div><p className="font-semibold text-sm mb-3">Fale com a Drica</p><a className="text-[#f6e0da] text-xs flex items-center gap-2" target="_blank" rel="noreferrer" href={`https://wa.me/${WHATSAPP}`}><MessageCircle size={15}/> (11) 96081-4357</a>{catalog.settings.instagram_url?<a className="text-[#f6e0da] text-xs flex items-center gap-2 mt-3" target="_blank" rel="noreferrer" href={catalog.settings.instagram_url}><Instagram size={15}/> Instagram</a>:<p className="text-[#d8bfba] text-xs mt-3">Instagram a cadastrar</p>}<button onClick={()=>setTrack(true)} className="text-left mt-3 text-xs underline text-[#f6e0da]">Acompanhar encomenda</button></div></div><div className="border-t border-white/20 max-w-6xl mx-auto mt-8 pt-5 flex justify-between text-[11px] text-[#d8bfba] flex-wrap gap-2"><span>© {new Date().getFullYear()} Drica Doces · Feito com amor · <a href="/privacidade.html" target="_blank" rel="noreferrer" className="underline">Privacidade</a> · <a href="https://commons.wikimedia.org/wiki/File:Brigadeiro.jpg" target="_blank" rel="noopener noreferrer" className="underline">Foto: Mayra (Maych) / Commons (CC BY-SA 2.0)</a></span><button onClick={()=>setAdmin(true)} className="hover:text-white flex gap-1 items-center"><Lock size={13}/> Acesso restrito</button></div></footer>
    <button aria-label="Abrir carrinho" onClick={()=>setDrawer(true)} className="fixed bottom-[max(1rem,env(safe-area-inset-bottom))] left-4 right-4 z-30 md:hidden bg-cocoa text-white rounded-2xl shadow-2xl min-h-14 px-5 py-3 flex gap-2 items-center justify-center text-sm font-bold hover:bg-rose"><ShoppingBag size={17}/> {count} {count===1?'item':'itens'} · Ver carrinho</button>
    <CartDrawer open={drawer} onClose={()=>setDrawer(false)} cart={cart} products={catalog.products} settings={catalog.settings} onQty={qty} onRemove={id=>setCart(p=>p.filter(x=>(x.line_key||x.option_id)!==id))} onCheckout={()=>go('encomendar')} onBrowse={()=>go('cardapio')}/>{modalProduct&&<ProductModal key={modalProduct.id} product={modalProduct} settings={catalog.settings} onClose={()=>setModalProduct(null)} onAdd={addItem}/>} {track&&<TrackModal onClose={()=>setTrack(false)}/>} {admin&&<AdminPanel onClose={()=>setAdmin(false)} onNotify={flash} onCatalogChanged={refresh}/>}<LargeOrderModal quote={largeQuote} onClose={()=>setLargeQuote(null)}/><Toast msg={toast}/>{!isLive&&<div className="fixed bottom-24 right-4 z-20 bg-[#fff9ee]/95 border border-[#e4ceb0] rounded-xl px-3 py-2 text-[10px] text-[#946935] shadow max-w-[190px]">Modo demonstração: pedidos salvos apenas neste aparelho.</div>}</div>}
